describe('Remember Me Functionality', () => {
  const testUser = {
    email: 'testuser@example.com',
    password: 'SecurePassword123!'
  };

  const loginUrl = 'http://localhost:3000/login';
  const dashboardUrl = 'http://localhost:3000/dashboard';

  beforeEach(() => {
    cy.clearCookies();
    cy.clearLocalStorage();
    cy.visit(loginUrl);
  });

  it('should persist user session when Remember Me checkbox is checked', () => {
    // Fill in login credentials
    cy.get('input[name="email"]').type(testUser.email);
    cy.get('input[name="password"]').type(testUser.password);

    // Check the Remember Me checkbox
    cy.get('input[type="checkbox"][name="rememberMe"]').check();
    cy.get('input[type="checkbox"][name="rememberMe"]').should('be.checked');

    // Submit login form
    cy.get('button[type="submit"]').click();

    // Verify successful login and redirect to dashboard
    cy.url().should('include', dashboardUrl);
    cy.get('[data-testid="user-welcome"]').should('contain', testUser.email);

    // Verify that remember me token is stored
    cy.getCookie('rememberMeToken').should('exist');
    cy.getAllCookies().then((cookies) => {
      const rememberMeCookie = cookies.find(c => c.name === 'rememberMeToken');
      expect(rememberMeCookie).to.exist;
      expect(rememberMeCookie.expiration).to.be.greaterThan(Date.now() / 1000 + 86400 * 29); // At least 29 days
    });

    // Simulate closing and reopening browser by clearing session storage but keeping cookies
    cy.clearLocalStorage();
    cy.visit(dashboardUrl);

    // User should still be logged in
    cy.url().should('include', dashboardUrl);
    cy.get('[data-testid="user-welcome"]').should('contain', testUser.email);
    cy.get('[data-testid="logout-button"]').should('be.visible');
  });

  it('should not persist session when Remember Me checkbox is unchecked', () => {
    // Fill in login credentials
    cy.get('input[name="email"]').type(testUser.email);
    cy.get('input[name="password"]').type(testUser.password);

    // Ensure Remember Me checkbox is NOT checked
    cy.get('input[type="checkbox"][name="rememberMe"]').should('not.be.checked');

    // Submit login form
    cy.get('button[type="submit"]').click();

    // Verify successful login
    cy.url().should('include', dashboardUrl);
    cy.get('[data-testid="user-welcome"]').should('contain', testUser.email);

    // Verify that remember me token is NOT stored
    cy.getCookie('rememberMeToken').should('not.exist');

    // Clear session storage to simulate closing browser
    cy.clearLocalStorage();
    cy.clearCookies();

    // Try to access dashboard directly
    cy.visit(dashboardUrl);

    // User should be redirected to login page
    cy.url().should('include', loginUrl);
    cy.get('input[name="email"]').should('be.visible');
  });

  it('should handle expired Remember Me token gracefully', () => {
    // Set an expired remember me cookie
    cy.setCookie('rememberMeToken', 'expired_token_value', {
      expiration: Math.floor(Date.now() / 1000) - 3600 // Expired 1 hour ago
    });

    // Try to access dashboard
    cy.visit(dashboardUrl);

    // Should redirect to login page
    cy.url().should('include', loginUrl);
    cy.get('[data-testid="error-message"]').should('contain', 'Session expired');
  });

  it('should allow user to toggle Remember Me checkbox before login', () => {
    // Verify checkbox is initially unchecked
    cy.get('input[type="checkbox"][name="rememberMe"]').should('not.be.checked');

    // Check the checkbox
    cy.get('input[type="checkbox"][name="rememberMe"]').check();
    cy.get('input[type="checkbox"][name="rememberMe"]').should('be.checked');

    // Uncheck the checkbox
    cy.get('input[type="checkbox"][name="rememberMe"]').uncheck();
    cy.get('input[type="checkbox"][name="rememberMe"]').should('not.be.checked');

    // Check again
    cy.get('input[type="checkbox"][name="rememberMe"]').check();
    cy.get('input[type="checkbox"][name="rememberMe"]').should('be.checked');
  });

  it('should maintain Remember Me preference across multiple sessions', () => {
    // First login with Remember Me enabled
    cy.get('input[name="email"]').type(testUser.email);
    cy.get('input[name="password"]').type(testUser.password);
    cy.get('input[type="checkbox"][name="rememberMe"]').check();
    cy.get('button[type="submit"]').click();

    cy.url().should('include', dashboardUrl);
    cy.getCookie('rememberMeToken').should('exist');

    // Logout
    cy.get('[data-testid="logout-button"]').click();
    cy.url().should('include', loginUrl);

    // Clear session but keep cookies
    cy.clearLocalStorage();

    // Visit dashboard again
    cy.visit(dashboardUrl);

    // Should still be logged in due to Remember Me token
    cy.url().should('include', dashboardUrl);
    cy.get('[data-testid="user-welcome"]').should('contain', testUser.email);
  });

  it('should clear Remember Me token on explicit logout', () => {
    // Login with Remember Me enabled
    cy.get('input[name="email"]').type(testUser.email);
    cy.get('input[name="password"]').type(testUser.password);
    cy.get('input[type="checkbox"][name="rememberMe"]').check();
    cy.get('button[type="submit"]').click();

    cy.url().should('include', dashboardUrl);
    cy.getCookie('rememberMeToken').should('exist');

    // Click logout button
    cy.get('[data-testid="logout-button"]').click();

    // Verify redirect to login
    cy.url().should('include', loginUrl);

    // Verify Remember Me token is cleared
    cy.getCookie('rememberMeToken').should('not.exist');

    // Try to access dashboard
    cy.visit(dashboardUrl);

    // Should be redirected to login
    cy.url().should('include', loginUrl);
  });
});
